<script setup>
import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {RefreshCw,ExternalLink} from 'lucide-vue-next';import {api,money,date,safeUrl} from '../services/api';import {useArchive} from '../stores/archive'
const route=useRoute(),store=useArchive(),figure=ref(null),prices=ref(null),used=ref(null),busy=ref(false),error=ref(''),refreshResult=ref(null)
const suffix=route.query.variant?'?variant_id='+route.query.variant:''
async function load(){const [f,p,u]=await Promise.all([api('/figures/'+route.params.id),api(`/figures/${route.params.id}/prices${suffix}`),api(`/figures/${route.params.id}/used-market${suffix}`)]);figure.value=f;prices.value=p;used.value=u}
onMounted(async()=>{try{await load()}catch(e){error.value=e.message}})
async function refresh(){busy.value=true;error.value='';try{refreshResult.value=await api(`/figures/${route.params.id}/prices/refresh${suffix}`,{method:'POST',token:store.adminToken});await load()}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><section class="page-heading"><p class="eyebrow">PRICE OBSERVATORY</p><h1>가격과 시장</h1><RouterLink v-if="figure" :to="'/figures/'+figure.id">{{figure.name_original}} ↗</RouterLink></section><p v-if="error" class="error" role="alert">{{error}}</p><template v-if="prices"><div class="price-metrics"><div><span>일본 공식 발매가</span><strong>{{money(prices.japan_release_price?.price_amount)}}</strong><small>해당 버전의 공식 발매가</small></div><div><span>국내 신품 최저 확인가</span><strong>{{money(prices.lowest_verified_krw,'KRW')}}</strong><small>배송비 제외 · 최근 관측 기준</small></div><div><span>수집된 중고 매물</span><strong>{{used.listings.length}}<small> 건</small></strong><small>판매 희망가 기준</small></div></div><section class="section"><div class="section-title"><h2>국내 판매처별 관측</h2><button v-if="store.isAdmin" class="button ghost" @click="refresh" :disabled="busy"><RefreshCw :size="16" :class="{spin:busy}"/> {{busy?'검색·검증 중…':'새 가격 검색'}}</button></div><p v-if="!store.isAdmin" class="fine-print">새 가격 검색은 <RouterLink to="/status">관리자 연결</RouterLink> 후 사용할 수 있습니다.</p><p class="fine-print">{{prices.note}}</p><div v-if="!prices.retail_prices.length" class="empty">확인된 국내 판매 가격이 없습니다. 금액을 추정해 표시하지 않습니다.</div><div v-else class="table-wrap"><table><thead><tr><th>판매처</th><th>가격</th><th>종류·상태</th><th>제품 일치</th><th>확인일</th><th>원문</th></tr></thead><tbody><tr v-for="p in prices.retail_prices" :key="p.id"><td>{{p.retailer}}</td><td>{{money(p.amount,p.currency)}}</td><td>{{p.price_type}} / {{p.availability}}</td><td>{{p.match_status}} {{p.stale?'· 오래된 관측':''}}</td><td>{{date(p.observed_at)}}</td><td><a :href="safeUrl(p.product_url)" target="_blank" rel="noopener noreferrer">확인 ↗</a></td></tr></tbody></table></div><div v-if="refreshResult" class="notice"><p>{{refreshResult.cached?'캐시 사용':'검색 완료'}} · 신규 가격 관측 {{refreshResult.observations_added}}건</p><ul><li v-for="c in refreshResult.candidates" :key="c.url"><a :href="safeUrl(c.url)" target="_blank" rel="noopener noreferrer">{{c.title}} ↗</a> <small>{{c.status}}</small></li></ul></div></section><section class="section"><div class="section-title"><h2>중고 매물 시세</h2><span class="tag">ASKING PRICE</span></div><p class="fine-print">{{used.note}}</p><div class="empty" v-if="!used.statistics.length">동일 제품·상태로 검증된 표본이 없습니다.</div><div class="table-wrap" v-else><table><thead><tr><th>플랫폼</th><th>상태 / 판매 상태</th><th>통화</th><th>표본</th><th>중앙값</th><th>비고</th></tr></thead><tbody><tr v-for="(s,i) in used.statistics" :key="i"><td>{{s.platform}}</td><td>{{s.condition}} / {{s.status}}</td><td>{{s.currency}}</td><td>{{s.count}}</td><td>{{money(s.median,s.currency)}}</td><td>{{s.note}}</td></tr></tbody></table></div><div class="source-buttons"><template v-for="link in used.search_links" :key="link.name"><a v-if="link.url" :href="safeUrl(link.url)" target="_blank" rel="noopener noreferrer" class="button ghost">{{link.name}} 검색 <ExternalLink :size="14"/></a><span v-else class="button ghost" aria-disabled="true">{{link.name}} · {{link.reason}}</span></template></div><p class="fine-print">외부 검색 결과는 제품 일치 검증 전입니다. 플랫폼별 접근 권한이 확보되기 전에는 자동 수집하지 않습니다.</p><div class="table-wrap" v-if="used.listings.length"><table><thead><tr><th>플랫폼</th><th>희망가</th><th>상태</th><th>검증</th><th>출처</th></tr></thead><tbody><tr v-for="l in used.listings" :key="l.id"><td>{{l.platform}}</td><td>{{money(l.asking_price,l.currency)}}</td><td>{{l.condition}} / {{l.listing_status}}</td><td>{{l.match_status}} {{l.stale?'· 오래됨':''}}</td><td><a :href="safeUrl(l.listing_url)" target="_blank" rel="noopener noreferrer">매물 보기 ↗</a></td></tr></tbody></table></div></section></template></template>
